const clean = [];

function extractSource(content) {
  if (!content) return "unknown";

  const str = typeof content === "string" ? content : JSON.stringify(content);

  const canonicalMatch = str.match(/<link[^>]*rel=["']?canonical["']?[^>]*href=["'](.*?)["']/i);
  if (canonicalMatch && canonicalMatch[1]) {
    const url = canonicalMatch[1].trim();
    const domain = url.match(/https?:\/\/(www\.)?([^\/]+)/i);
    return domain ? domain[2] : url;
  }

  const titleMatch = str.match(/<title[^>]*>(.*?)<\/title>/i);
  if (titleMatch && titleMatch[1]) {
    return titleMatch[1].trim();
  }

  const domainMatch = str.match(/https?:\/\/(www\.)?([^\/\s]+)/i);
  if (domainMatch && domainMatch[2]) {
    return domainMatch[2];
  }

  return "unknown";
}

function extractTitle(str) {
  const m = str.match(/<title[^>]*>(.*?)<\/title>/i);
  if (m) return m[1].trim();

  const h1 = str.match(/<h1[^>]*>(.*?)<\/h1>/i);
  return h1 ? h1[1].trim() : "";
}

function extractSubtitle(str) {
  const meta = str.match(/<meta[^>]*name=["']description["'][^>]*content=["'](.*?)["']/i);
  if (meta) return meta[1].trim();

  const og = str.match(/<meta[^>]*property=["']og:description["'][^>]*content=["'](.*?)["']/i);
  return og ? og[1].trim() : "";
}

function extractSnippet(html) {
  if (!html) return "";

  let text = html
    .replace(/<script[\s\S]*?<\/script>/gi, "")
    .replace(/<style[\s\S]*?<\/style>/gi, "")
    .replace(/<nav[\s\S]*?<\/nav>/gi, "")
    .replace(/<footer[\s\S]*?<\/footer>/gi, "")
    .replace(/<header[\s\S]*?<\/header>/gi, "")
    .replace(/<[^>]+>/g, " ")
    .replace(/\s+/g, " ")
    .trim();

  // aggressive junk removal
  const junkPatterns = [
    "skip to content",
    "buy tickets",
    "read more",
    "facetwp",
    "all live events",
    "home",
    "menu",
    "cookie",
    "accept cookies",
    "google-site-verification",
    "top of page",
    "reset"
  ];

  for (const j of junkPatterns) {
    text = text.replace(new RegExp(j, "gi"), "");
  }

  text = text.replace(/\s+/g, " ").trim();

  // split into sentences
  const sentences = text
    .split(".")
    .map(s => s.trim())
    .filter(s =>
      s.length > 25 &&
      !junkPatterns.some(j => s.toLowerCase().includes(j))
    );

  return sentences.slice(0, 3).join(". ").slice(0, 350);
}

function extractDate(str = "") {
  if (!str) return "";

  const patterns = [
    // Wed, 22 Apr / Wed 22 Apr / Wed 22 April
    /\b(Mon|Tue|Wed|Thu|Fri|Sat|Sun)[a-z]*,?\s?\d{1,2}\s?(Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec)[a-z]*\b/i,

    // 22 Apr 2026 / 22 Apr / 22 April 2026
    /\b\d{1,2}\s?(Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec)[a-z]*\.?\s?\d{0,4}\b/i,

    // Apr 22 / April 22
    /\b(Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec)[a-z]*\.?\s\d{1,2}\b/i,

    // Friday 12 / Sat 25
    /\b(Mon|Tue|Wed|Thu|Fri|Sat|Sun)[a-z]*\s\d{1,2}\b/i,

    // ISO-ish: 2026-04-22
    /\b\d{4}-\d{2}-\d{2}\b/,

    // “22nd April”, “1st May”
    /\b\d{1,2}(st|nd|rd|th)\s?(Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec)[a-z]*\b/i,

    // Time-bound phrases (weak signal but better than empty)
    /\b(today|tonight|this weekend|this friday|next friday|this sunday)\b/i,
  ];

  for (const p of patterns) {
    const match = str.match(p);
    if (match) return match[0];
  }

  return "";
}

function extractVenue(str) {
  const venues = ["Brixton", "Soho", "Camden", "Shoreditch", "Hackney", "Islington"];
  for (const v of venues) {
    if (str.includes(v)) return v;
  }
  return "";
}

for (const item of items) {
  const content = item.json.raw?.data ?? item.json.raw ?? item.json;
  const str = typeof content === "string" ? content : JSON.stringify(content);

  clean.push({
    source: extractSource(str),
    title: extractTitle(str),
    subtitle: extractSubtitle(str),
    snippet: extractSnippet(str),
    date: extractDate(str),
    venue: extractVenue(str),    
    content: str // keep raw for now (useful for debugging/filter node)
  });
}

return [
  {
    json: {
      data: clean
    }
  }
];

const results = items.map(item => ({
  section: item.json.section,
  source: item.json.source || "unknown",
  title: item.json.title || "",
  subtitle: item.json.subtitle || "",
  snippet: item.json.snippet || "",
  date: item.json.date || "",
  venue: item.json.venue || "",
  price: item.json.price || ""
}));

return [
  {
    json: {
      totalExtracted: results.length,
      results
    }
  }
];

function cleanText(s) {
  return (s || "")
    .toLowerCase()
    .replace(/\s+/g, " ")
    .trim();
}

function makeKey(item) {
  return cleanText(item.title + "|" + item.date + "|" + item.venue);
}

/* =========================
   LIGHT JUNK FILTER ONLY
   ========================= */
function isValid(entry) {
  if (!entry.title || entry.title.trim().length < 5) return false;

  const t = cleanText(
    entry.title + " " + (entry.subtitle || "") + " " + (entry.snippet || "")
  );

  if (t.length < 10) return false;

  const hardJunk = [
    "cookie",
    "subscribe",
    "javascript",
    "enable",
    "access denied"
  ];

  return !hardJunk.some(j => t.includes(j));
}

/* =========================
   MAIN
   ========================= */
const seen = new Set();
const output = [];

for (const item of items) {
  const data = item.json.data || item.json.results || [];

  for (const entry of data) {

    if (!isValid(entry)) continue;

    /* =========================
       DEDUPE ONLY
       ========================= */
    const key = makeKey(entry);
    if (seen.has(key)) continue;
    seen.add(key);

    output.push({
      source: entry.source || "unknown",
      title: entry.title || "",
      subtitle: entry.subtitle || "",
      snippet: entry.snippet || "",
      date: entry.date || "",
      venue: entry.venue || ""  
    });
  }
}

/* =========================
   IMPROVED SCORING (CULTURE + DISCOVERY BOOSTED)
   ========================= */
function score(e) {
  const t = cleanText(e.title + " " + (e.snippet || ""));

  let s = 0;

  // NIGHTLIFE
  if (t.includes("reggaeton")) s += 6;
  if (t.includes("club")) s += 4;
  if (t.includes("party")) s += 3;
  if (t.includes("dj")) s += 3;

  // CULTURE (BOOSTED — FIXES YOUR “LOW ENERGY MISSING” ISSUE)
  if (t.includes("cinema")) s += 7;
  if (t.includes("exhibition")) s += 7;
  if (t.includes("museum")) s += 7;
  if (t.includes("theatre")) s += 6;
  if (t.includes("art")) s += 5;

  // LIVE / SOCIAL
  if (t.includes("live")) s += 3;
  if (t.includes("music")) s += 3;

  // DISCOVERY SOURCES (IMPORTANT FOR TIMEOUT / FEVER / LATINOLIFE)
  if (t.includes("things to do")) s += 6;
  if (t.includes("this week")) s += 5;
  if (t.includes("what's on")) s += 5;

  return s;
}

output.sort((a, b) => score(b) - score(a));

/* =========================
   IMPORTANT: GIVE CLAUDE MORE ROOM
   ========================= */

return [
  {
    json: {
      totalBefore: items.length,
      totalAfter: output.length,
      data: output.slice(0, 60)
    }
  }
];

const expanded = [];

function push(item) {
  const { Content, content, html, ...rest } = item;
  expanded.push(rest);
}

/* =========================
   EXPAND TIMEOUT / CURATED LISTS
   ========================= */
function expandCurated(entry) {

  const text = (entry.title + " " + entry.subtitle + " " + entry.snippet).toLowerCase();

  // ALWAYS create base
  push({ ...entry, category: "culture" });

  // FORCE MULTIPLE DERIVATIONS (THIS IS THE KEY FIX)

  if (text.includes("exhibition") || text.includes("museum")) {
    push({ ...entry, category: "low_energy", title: "Museum & Exhibition Pick" });
    push({ ...entry, category: "low_energy", title: "Gallery & Culture Walks" });
  }

  if (text.includes("cinema") || text.includes("film")) {
    push({ ...entry, category: "low_energy", title: "Cinema Picks This Week" });
    push({ ...entry, category: "low_energy", title: "Cult / Indie Screenings" });
  }

  if (text.includes("things to do") || text.includes("week")) {
    push({ ...entry, category: "today", title: "Top London Things To Do" });
    push({ ...entry, category: "today", title: "Editor's Weekly Picks" });
    push({ ...entry, category: "squirrel", title: "Hidden Gems This Week" });
    push({ ...entry, category: "weekend", title: "Weekend Highlights From Guide" });
  }

  // ALWAYS inject “bonus discovery”
  push({ ...entry, category: "bonus", title: "More from Editorial Guide" });
}

/* =========================
   VENUES (Egg, Brixton, PostBar, etc.)
   ========================= */
function expandVenue(entry) {
  const text = entry.snippet || "";

  const dates = text.match(
    /(Mon|Tue|Wed|Thu|Fri|Sat|Sun).*?\d{1,2}/g
  ) || [];

  if (dates.length === 0) {
    push({
      ...entry,
      category: "weekend"
    });
  } else {
    for (const d of dates.slice(0, 3)) {
      push({
        ...entry,
        category: "weekend",
        snippet: `${entry.snippet || ""} | Event scheduled: ${d}`
      });
    }
  }
}

/* =========================
   CULTURE ARTICLES (LatinoLife, Metro)
   ========================= */
function expandArticle(entry) {

  push({ ...entry, category: "squirrel" });

  // FORCE MULTIPLE INTERPRETATIONS
  push({ ...entry, category: "squirrel", title: entry.title });
  push({ ...entry, category: "bonus", title: "Cultural Insight" });
  push({ ...entry, category: "bonus", title: "Related Latin Scene Event" });
  push({ ...entry, category: "today", title: "Latin Culture Highlight This Week" });
}

function expandFever(entry) {

  push({ ...entry, category: "today" });
  push({ ...entry, category: "weekend" });
  push({ ...entry, category: "weekend" });
  push({ ...entry, category: "squirrel" });
}

/* =========================
   MAIN LOOP
   ========================= */
for (const item of items) {

  const data = item.json.data || [];

  for (const entry of data) {

    const src = (entry.source || "").toLowerCase();

    if (src.includes("timeout") || src.includes("fever")) {
      expandCurated(entry);
      continue;
    }

    if(src.includes("fever")) {
      expandFever(entry);
    }

    if (
      src.includes("egg") ||
      src.includes("electric") ||
      src.includes("postbar") ||
      src.includes("hootananny") ||
      src.includes("brixton") ||
      src.includes("jungla")
    ) {
      expandVenue(entry);
      continue;
    }

    if (
      src.includes("latinolife") ||
      src.includes("metro")
    ) {
      expandArticle(entry);
      continue;
    }

    /* fallback (NO DATA LOSS) */
    push({
      ...entry,
      category: "bonus"
    });
  }
}

return [
  {
    json: {
      expandedCount: expanded.length,
      data: expanded
    }
  }
];

const grouped = {
  TODAY: [],
  SQUIRREL: [],
  LOW_ENERGY: [],
  WEEKEND: [],
  BONUS: []
};

for (const item of $json.data) {

  const t = (item.title + " " + item.snippet).toLowerCase();

  if (t.includes("party") || t.includes("club") || t.includes("dj") || t.includes("reggaeton")) {
    grouped.TODAY.push(item);
    continue;
  }

  if (t.includes("cinema") || t.includes("exhibition") || t.includes("museum")) {
    grouped.LOW_ENERGY.push(item);
    continue;
  }

  if (t.includes("week") || t.includes("what's on") || t.includes("festival")) {
    grouped.WEEKEND.push(item);
    continue;
  }

  if (t.includes("latino") || t.includes("metro") || t.includes("trend")) {
    grouped.SQUIRREL.push(item);
    continue;
  }

  grouped.BONUS.push(item);
}

return [{ json: { grouped } }];

const flat = [];
for (const [section, items] of Object.entries($json.grouped || {})) {
  for (const item of items || []) {
    flat.push({ section, ...item });
  }
}
return flat;

const clean = (t) =>
  (t || "")
    .replace(/&#039;/g, "'")
    .replace(/&amp;/g, "&")
    .replace(/\s+/g, " ")
    .slice(0, 120);

const MAX_ITEMS = 15;

const results = items.slice(0, MAX_ITEMS).map(({ json }) => ({
  section: json.section,
  source: json.source,
  title: json.title,
  subtitle: clean(json.subtitle),
  snippet: clean(json.snippet),  // capped
  date: json.date,
  venue: json.venue,  
}));

return results;

const cheerio = require('cheerio');

const expanded = [];

for (const item of items) {
  const data = item.json.data || [];

  for (const entry of data) {
    const src = (entry.source || "").toLowerCase();
    const html = entry.content || entry.html || entry.Content || "";

    if (!html) {
      expanded.push({ source: entry.source, title: entry.title || "Event", snippet: entry.snippet || "", category: "bonus" });
      continue;
    }

    const $ = cheerio.load(html);
    $('script, style, nav, footer, header, [class*="cookie"], [class*="banner"], [class*="ad"]').remove();

    // ---- TIMEOUT ----
    if (src.includes("timeout")) {
      $('article, [class*="card"], [class*="tile"], [class*="editorial"]').each((i, el) => {
        const title = $(el).find('h2, h3, h4, [class*="title"]').first().text().trim();
        const snippet = $(el).find('p, [class*="desc"], [class*="summary"]').first().text().trim();
        const link = $(el).find('a').first().attr('href') || "";
        if (!title || title.length <= 3) return;
        if (title === '[title]' || title.includes('[') || !snippet) return;
        expanded.push({
          source: entry.source,
          title,
          snippet: snippet.substring(0, 200),
          link: link.startsWith('http') ? link : `https://timeout.com${link}`,
          category: "culture"
        });
      });
      continue;
    }

    // ---- DICE.FM ----
    if (src.includes("dice")) {
      $('[class*="event"], [class*="EventCard"], [class*="listing"], article').each((i, el) => {
        const title = $(el).find('h2, h3, [class*="title"], [class*="name"]').first().text().trim();
        const date = $(el).find('[class*="date"], time, [class*="when"]').first().text().trim();
        const venue = $(el).find('[class*="venue"], [class*="location"]').first().text().trim();
        if (!title || title.length <= 3) return;
        if (title.includes('[')) return;
        expanded.push({
          source: entry.source,
          title,
          snippet: [date, venue].filter(Boolean).join(' | '),
          category: "today"
        });
      });
      continue;
    }

    // ---- FEVER ----
    // ---- FEVER (FIXED: JSON-LD FIRST APPROACH) ----
    if (src.includes("fever")) {    
      const jsonLdBlocks = [];

      // 1. COLLECT ALL JSON-LD BLOCKS
      $('script[type="application/ld+json"]').each((i, el) => {
        try {
          const raw = $(el).html();
          if (!raw) return;

          const parsed = JSON.parse(raw);

          // handle arrays or single objects
          if (Array.isArray(parsed)) {
            jsonLdBlocks.push(...parsed);
          } else {
            jsonLdBlocks.push(parsed);
          }
        } catch (e) {
          // ignore bad JSON blocks
        }
      });

      // 2. EXTRACT EVENTS FROM JSON-LD
      for (const block of jsonLdBlocks) {

        // Fever often uses Event schema OR nested graphs
        const items = block['@graph'] ? block['@graph'] : [block];

        for (const item of items) {

          if (!item) continue;

          const title =
            item.name ||
            item.headline ||
            item.eventName ||
            "";

          if (!title || title.length < 3) continue;

          const startDate =
            item.startDate ||
            item.start_date ||
            item.date ||
            "";

          const venue =
            item.location?.name ||
            item.location ||
            item.address?.name ||
            "";

          const description =
            item.description ||
            item.summary ||
            item.abstract ||
            "";

          const snippet = [
            description,
            startDate,
            venue
          ]
            .filter(Boolean)
            .join(" | ")
            .replace(/\s+/g, " ")
            .trim();

          expanded.push({
            source: entry.source,
            title: title.trim(),
            snippet: snippet || "no-snippet",
            date: startDate || "",
            venue: typeof venue === "string" ? venue : (venue?.name || ""),
            category: "weekend"
          });
        }
      }

      // 3. FALLBACK (ONLY IF JSON-LD FAILS)
      if (jsonLdBlocks.length === 0) {       
      }

      continue;
    }

    // ---- LATIN SITES ----
    if (src.includes("latinolife") || src.includes("latin-candy")) {
      $('article, [class*="post"], [class*="event"], [class*="entry"]').each((i, el) => {
        const title = $(el).find('h2, h3, [class*="title"]').first().text().trim();
        const snippet = $(el).find('p').first().text().trim();
        const date = $(el).find('[class*="date"], time').first().text().trim();
        if (!title || title.length <= 3) return;
        if (title.includes('[')) return;
        expanded.push({
          source: entry.source,
          title,
          snippet: [date, snippet.substring(0, 150)].filter(Boolean).join(' | '),
          category: "squirrel"
        });
      });
      continue;
    }

    // ---- SINGLE VENUES ----
    if (
      src.includes("egg") || src.includes("electric") ||
      src.includes("postbar") || src.includes("hootananny") ||
      src.includes("brixton") || src.includes("egglondon")
    ) {
      $('[class*="event"], [class*="gig"], [class*="night"], [class*="show"], article, li').each((i, el) => {
        const title = $(el).find('h2, h3, h4, [class*="title"], [class*="name"]').first().text().trim();
        const date = $(el).find('[class*="date"], time, [class*="when"]').first().text().trim();
        const desc = $(el).find('p, [class*="desc"]').first().text().trim();
        if (!title || title.length <= 3) return;
        if (title.includes('[')) return;
        expanded.push({
          source: entry.source,
          title,
          snippet: [date, desc.substring(0, 150)].filter(Boolean).join(' | '),
          category: "weekend"
        });
      });
      continue;
    }

    // ---- CINEMAS & THEATRES ----
    if (
      src.includes("prince") || src.includes("bfi") ||
      src.includes("garden") || src.includes("etcetera") ||
      src.includes("lion") || src.includes("cinema")
    ) {
      $('[class*="film"], [class*="show"], [class*="event"], [class*="screening"], [class*="production"], article, li').each((i, el) => {
        const title = $(el).find('h2, h3, h4, [class*="title"]').first().text().trim();
        const date = $(el).find('[class*="date"], time, [class*="when"]').first().text().trim();
        const desc = $(el).find('p, [class*="desc"]').first().text().trim();
        if (!title || title.length <= 3) return;
        if (title.includes('[')) return;
        expanded.push({
          source: entry.source,
          title,
          snippet: [date, desc.substring(0, 150)].filter(Boolean).join(' | '),
          category: "low_energy"
        });
      });
      continue;
    }

    // ---- FALLBACK ----
    expanded.push({
      source: entry.source,
      title: entry.title || "Event",
      snippet: entry.snippet || "",
      category: "bonus"
    });
  }
}

const deduped = [];
const seen = new Set();

for (const item of expanded) {
  const key = `${item.source}|${item.title}`;

  if (seen.has(key)) continue;
  seen.add(key);

  deduped.push(item);
}

return [{
  json: {
    expandedCount: deduped.length,
    data: deduped
  }
}];

const data = items[0].json.data || [];

// Deduplicate by title
const seen = new Set();
const deduped = data.filter(item => {
  const key = item.title.toLowerCase().trim();
  if (seen.has(key)) return false;
  seen.add(key);
  return true;
});

// Cap at 150 most relevant
const capped = deduped.slice(0, 150);

return [{
  json: {
    expandedCount: capped.length,
    data: capped
  }
}];
